     "summary": "据印度尼西亚气象、气候和地球物理局消息，印尼15日清晨发生7.7级地震。 中国地震台网正式测定：8月15日5时58分，在印尼弗洛勒斯岛附近海域(南纬8.40度，东经121.40度)发生7.7级地震，震源深度20公里。 另据欧洲-地中海地震中心15日消息，预计地震将引发海啸。 印尼东努沙登加拉省部分地区在7.7级地震后报告出现严重损毁。目前，当地有关部门仍处于高度戒备状态。 印尼气象、气候与地球物理局报告显示，强震发生后，震中附近又连续出现多次5级以上地震。其中当地时间5时06",
